<?php/** * Transparency Drawer — V1.0.8 * * FIXED: Color logic for Pro/Agency * FIXED: Empty color fallbacks * FIXED: White label (Agency) now uses custom colors * FIXED: All variables prefixed with megagovern_ for WP.org compliance * * @package MegaGovern * @since   1.0.8 */if ( ! defined( 'ABSPATH' ) ) {    exit;}$megagovern_settings     = $this->get_settings();$megagovern_summary      = $this->get_summary();$megagovern_is_dismissed = isset( $_COOKIE['megagovern_transparency_dismissed'] );if ( $megagovern_is_dismissed ) {    return;}// ─── SETTINGS ───$megagovern_is_free        = ! $megagovern_settings['is_pro'] && ! $megagovern_settings['is_agency'];$megagovern_white_label    = $megagovern_settings['white_label'] ?? false;$megagovern_badge_text     = ! empty( $megagovern_settings['custom_text'] ) ? $megagovern_settings['custom_text'] : __( 'AI Transparency Notice', 'megagovern' );$megagovern_position       = $megagovern_settings['position'];$megagovern_position_class = 'mga-badge--' . $megagovern_position;// ─── COLORS — FIXED ───// Only Free tier is locked to MegaGovern blue.// Pro, Agency, and White Label use custom brand colors.if ( $megagovern_is_free ) {    $megagovern_bg_color   = '#0052CC';    $megagovern_text_color = '#ffffff';    $megagovern_link_color = '#93c5fd';} else {    // Fallbacks for empty values    $megagovern_bg_color   = ! empty( $megagovern_settings['bg_color'] ) ? $megagovern_settings['bg_color'] : '#0052CC';    $megagovern_text_color = ! empty( $megagovern_settings['text_color'] ) ? $megagovern_settings['text_color'] : '#ffffff';    $megagovern_link_color = ! empty( $megagovern_settings['link_color'] ) ? $megagovern_settings['link_color'] : '#93c5fd';}// ─── LOGO — ALWAYS ON ───$megagovern_show_logo = true;// ─── POWERED BY ───$megagovern_show_powered = $megagovern_is_free ? true : ( $megagovern_settings['show_powered'] !== false );$megagovern_powered_text = ! empty( $megagovern_settings['powered_text'] ) ? $megagovern_settings['powered_text'] : __( 'Powered by MegaGovern', 'megagovern' );// ─── LOGO URL & STYLES ───$megagovern_logo_url   = MEGAGOVERN_URL . 'assets/images/megagovern-w-logo.svg';$megagovern_logo_class = 'mga-badge-logo';if ( $megagovern_is_free ) {    $megagovern_logo_class .= ' mga-badge-logo--free';    $megagovern_logo_style  = 'height:20px;width:auto;display:inline-block !important;flex-shrink:0;filter:brightness(0) invert(1);';} else {    $megagovern_logo_class .= ' mga-badge-logo--pro';    $megagovern_logo_style  = 'height:20px;width:auto;display:inline-block !important;flex-shrink:0;filter:drop-shadow(0 1px 4px rgba(0,0,0,0.5)) drop-shadow(0 0 2px rgba(0,0,0,0.3));';}// ─── URLS ───$megagovern_policy_url       = $megagovern_settings['policy_page'] ? get_permalink( $megagovern_settings['policy_page'] ) : home_url( '/ai-policy' );$megagovern_transparency_url = \MegaGovern\Verification::get_transparency_url();$megagovern_aitxt_url        = home_url( '/ai.txt' );?><!-- Floating Badge --><div id="mga-transparency-badge"     class="mga-transparency-badge <?php echo esc_attr( $megagovern_position_class ); ?>"     style="--mga-bg-color: <?php echo esc_attr( $megagovern_bg_color ); ?>;            --mga-text-color: <?php echo esc_attr( $megagovern_text_color ); ?>;            --mga-link-color: <?php echo esc_attr( $megagovern_link_color ); ?>;">    <button id="mga-transparency-toggle" class="mga-transparency-toggle"            aria-label="<?php esc_attr_e( 'Toggle transparency information', 'megagovern' ); ?>"            style="background: var(--mga-bg-color); color: var(--mga-text-color);">        <?php if ( $megagovern_show_logo ) : ?>            <img src="<?php echo esc_url( $megagovern_logo_url ); ?>"                 alt="<?php esc_attr_e( 'MegaGovern', 'megagovern' ); ?>"                 class="<?php echo esc_attr( $megagovern_logo_class ); ?>"                 style="<?php echo esc_attr( $megagovern_logo_style ); ?>">        <?php endif; ?>        <span class="mga-badge-text"><?php echo esc_html( $megagovern_badge_text ); ?></span>    </button>    <div id="mga-transparency-drawer" class="mga-transparency-drawer" style="display:none;">        <div class="mga-drawer-header">            <h3><?php esc_html_e( 'Transparency Center', 'megagovern' ); ?></h3>            <button id="mga-drawer-close" class="mga-drawer-close" aria-label="<?php esc_attr_e( 'Close', 'megagovern' ); ?>">                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">                    <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>                </svg>            </button>        </div>        <div class="mga-drawer-body">            <p class="mga-drawer-subtitle"><?php esc_html_e( 'Transparency Summary', 'megagovern' ); ?></p>            <div class="mga-drawer-stats">                <div class="mga-stat-row">                    <span class="mga-stat-label"><?php esc_html_e( 'Declared as Human Written', 'megagovern' ); ?></span>                    <span class="mga-stat-value"><?php echo esc_html( $megagovern_summary['human_pct'] ?? 0 ); ?>%</span>                </div>                <div class="mga-stat-row">                    <span class="mga-stat-label"><?php esc_html_e( 'Declared as AI Assisted', 'megagovern' ); ?></span>                    <span class="mga-stat-value"><?php echo esc_html( $megagovern_summary['assisted_pct'] ?? 0 ); ?>%</span>                </div>                <div class="mga-stat-row">                    <span class="mga-stat-label"><?php esc_html_e( 'Declared as AI Generated', 'megagovern' ); ?></span>                    <span class="mga-stat-value"><?php echo esc_html( $megagovern_summary['generated_pct'] ?? 0 ); ?>%</span>                </div>                <div class="mga-stat-row">                    <span class="mga-stat-label"><?php esc_html_e( 'Declared as Synthetic Media', 'megagovern' ); ?></span>                    <span class="mga-stat-value"><?php echo esc_html( $megagovern_summary['deepfake_pct'] ?? 0 ); ?>%</span>                </div>            </div>            <div class="mga-drawer-meta">                <div class="mga-meta-item">                    <span class="mga-meta-label"><?php esc_html_e( 'Last Declaration', 'megagovern' ); ?></span>                    <span class="mga-meta-value"><?php echo esc_html( date_i18n( get_option( 'date_format' ), strtotime( $megagovern_summary['last_updated'] ?? current_time( 'mysql' ) ) ) ); ?></span>                </div>                <div class="mga-meta-item">                    <span class="mga-meta-label"><?php esc_html_e( 'Transparency Records', 'megagovern' ); ?></span>                    <span class="mga-meta-value"><?php echo esc_html( number_format_i18n( $megagovern_summary['total'] ?? 0 ) ); ?></span>                </div>                <div class="mga-meta-item">                    <span class="mga-meta-label"><?php esc_html_e( 'Verification Status', 'megagovern' ); ?></span>                    <span class="mga-meta-value mga-status-verified">✅ <?php esc_html_e( 'Verified', 'megagovern' ); ?></span>                </div>            </div>            <div class="mga-drawer-links">                <a href="<?php echo esc_url( $megagovern_transparency_url ); ?>" class="mga-drawer-link" target="_blank" rel="noopener noreferrer" style="color: var(--mga-link-color);">                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>                    <?php esc_html_e( 'View Transparency Page', 'megagovern' ); ?>                </a>                <a href="<?php echo esc_url( $megagovern_policy_url ); ?>" class="mga-drawer-link" target="_blank" rel="noopener noreferrer" style="color: var(--mga-link-color);">                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>                    <?php esc_html_e( 'AI Policy', 'megagovern' ); ?>                </a>                <a href="<?php echo esc_url( $megagovern_aitxt_url ); ?>" class="mga-drawer-link" target="_blank" rel="noopener noreferrer" style="color: var(--mga-link-color);">                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16v16H4z"/><line x1="8" y1="8" x2="16" y2="8"/><line x1="8" y1="12" x2="16" y2="12"/><line x1="8" y1="16" x2="16" y2="16"/></svg>                    <?php esc_html_e( 'View AI.txt', 'megagovern' ); ?>                </a>            </div>            <div class="mga-drawer-footer">                <p class="mga-drawer-disclaimer">                    <?php esc_html_e( 'Transparency information aligned with EU AI Act Article 50 disclosure goals.', 'megagovern' ); ?>                </p>                <?php if ( $megagovern_show_powered ) : ?>                    <p class="mga-drawer-powered"><?php echo esc_html( $megagovern_powered_text ); ?></p>                <?php endif; ?>            </div>        </div>    </div></div>